#!/usr/bin/env python3
"""Single release identity for firmware, public manual and web version labels."""
import argparse,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
a=argparse.ArgumentParser();a.add_argument('--check',action='store_true');args=a.parse_args()
m=json.loads((ROOT/'release.json').read_text());assert re.fullmatch(r'\d+\.\d+(?:\.\d+)?',m['version']) and 1<=m['protocol']<128 and m['shared_voices'] in (8,12,16)
outputs={
 'firmware/src/release_meta.h':f'/* Generated by tools/gen_release_meta.py; edit release.json. */\n#define SM_RELEASE_VERSION "{m["version"]}"\n#define SM_RELEASE_BANNER "SYNTHMAVEN {m["version"]}"\n#define SM_RELEASE_PROTOCOL {m["protocol"]}u\n#define SM_RELEASE_VOICES {m["shared_voices"]}u\n',
 'docs/USER_MANUAL.md':(ROOT/'docs/USER_MANUAL.template.md').read_text()
}
for k in m:outputs['docs/USER_MANUAL.md']=outputs['docs/USER_MANUAL.md'].replace('{{'+k+'}}',str(m[k]))
# Current public labels are derived from metadata; historical release notes stay unchanged.
e=(ROOT/'web/editor.html').read_text()
e=re.sub(r'const SM_RELEASE = .*?;', 'const SM_RELEASE = '+json.dumps(m)+';',e,count=1)
e=re.sub(r'SynthMaven \d+\.\d+(?:\.\d+)? Editor','SynthMaven '+m['version']+' Editor',e)
e=re.sub(r'Version \d+\.\d+(?:\.\d+)? ·','Version '+m['version']+' ·',e)
e=re.sub(r'FELUCCA SYNTHMAVEN \d+\.\d+(?:\.\d+)? \(MOCK\)(?=" : opt.synthmaven)', 'FELUCCA SYNTHMAVEN '+m['version']+' (MOCK)',e)
e=re.sub(r'const SM_FILTER_MAP = .*?(?=/\* Compact performance protocol)' , 'const SM_FILTER_MAP = '+json.dumps(json.loads((ROOT/'assets/filter-capabilities.json').read_text()))+';\n',e,count=1,flags=re.S)
catalog=json.loads((ROOT/'assets/programs/catalog.json').read_text())
line='const SM_FACTORY_PROGRAM_BANK = '+json.dumps(catalog,separators=(',',':'))+';'
if 'const SM_FACTORY_PROGRAM_BANK =' in e:e=re.sub(r'^const SM_FACTORY_PROGRAM_BANK = [^\n]*$',lambda _:line,e,count=1,flags=re.M)
else:e=e.replace('const KORG_STOCK = ',line+'\nconst KORG_STOCK = ',1)
outputs['web/editor.html']=e
outputs['web/index_pkg.html']=re.sub(r'(SynthMaven|SYNTHMAVEN) \d+\.\d+(?:\.\d+)?', lambda x:x[1]+' '+m['version'],(ROOT/'web/index_pkg.html').read_text())
for p,s in outputs.items():
 path=ROOT/p
 if args.check:assert path.exists() and path.read_text()==s,f'{p} stale: run python3 tools/gen_release_meta.py'
 else:path.write_text(s)
print('Release metadata, firmware identity and manual labels match')
